// AlignmentDefinition preserves all public excelize.Alignment fields with typed categorical values.
type AlignmentDefinition struct {
	Horizontal      AlignmentHorizontal
	Indent          int
	JustifyLastLine bool
	ReadingOrder    AlignmentReadingOrder
	RelativeIndent  int
	ShrinkToFit     bool
	TextRotation    int
	Vertical        AlignmentVertical
	WrapText        bool
}

func (in AlignmentDefinition) ToExcelize() excelize.Alignment {
	out := excelize.Alignment{}
	out.Horizontal = string(in.Horizontal)
	out.Indent = in.Indent
	out.JustifyLastLine = in.JustifyLastLine
	out.ReadingOrder = uint64(in.ReadingOrder)
	out.RelativeIndent = in.RelativeIndent
	out.ShrinkToFit = in.ShrinkToFit
	out.TextRotation = in.TextRotation
	out.Vertical = string(in.Vertical)
	out.WrapText = in.WrapText
	return out
}
func AlignmentDefinitionFromExcelize(in excelize.Alignment) AlignmentDefinition {
	out := AlignmentDefinition{}
	out.Horizontal = AlignmentHorizontal(in.Horizontal)
	out.Indent = in.Indent
	out.JustifyLastLine = in.JustifyLastLine
	out.ReadingOrder = AlignmentReadingOrder(in.ReadingOrder)
	out.RelativeIndent = in.RelativeIndent
	out.ShrinkToFit = in.ShrinkToFit
	out.TextRotation = in.TextRotation
	out.Vertical = AlignmentVertical(in.Vertical)
	out.WrapText = in.WrapText
	return out
}

