// FontDefinition preserves all public excelize.Font fields with typed categorical values.
type FontDefinition struct {
	Bold         bool
	Italic       bool
	Underline    FontUnderline
	Family       string
	Size         float64
	Strike       bool
	Color        string
	ColorIndexed IndexedColor
	ColorTheme   *ThemeColor
	ColorTint    float64
	VertAlign    FontVerticalAlign
	Charset      *FontCharset
}

func (in FontDefinition) ToExcelize() excelize.Font {
	out := excelize.Font{}
	out.Bold = in.Bold
	out.Italic = in.Italic
	out.Underline = string(in.Underline)
	out.Family = in.Family
	out.Size = in.Size
	out.Strike = in.Strike
	out.Color = in.Color
	out.ColorIndexed = int(in.ColorIndexed)
	if in.ColorTheme != nil {
		value := int(*in.ColorTheme)
		out.ColorTheme = &value
	}
	out.ColorTint = in.ColorTint
	out.VertAlign = string(in.VertAlign)
	if in.Charset != nil {
		value := int(*in.Charset)
		out.Charset = &value
	}
	return out
}
func FontDefinitionFromExcelize(in excelize.Font) FontDefinition {
	out := FontDefinition{}
	out.Bold = in.Bold
	out.Italic = in.Italic
	out.Underline = FontUnderline(in.Underline)
	out.Family = in.Family
	out.Size = in.Size
	out.Strike = in.Strike
	out.Color = in.Color
	out.ColorIndexed = IndexedColor(in.ColorIndexed)
	if in.ColorTheme != nil {
		value := ThemeColor(*in.ColorTheme)
		out.ColorTheme = &value
	}
	out.ColorTint = in.ColorTint
	out.VertAlign = FontVerticalAlign(in.VertAlign)
	if in.Charset != nil {
		value := FontCharset(*in.Charset)
		out.Charset = &value
	}
	return out
}

